contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, make 2^256-1 deposits of 1 wei each
        for (uint i = 0; i < 255; i++) {
            vm.deal(address(this), 1);
            (bool ok, ) = address(c).call{value: 1}("");
            assertTrue(ok);
        }
        // At this point depositsCount should be 2^256-1 (max uint)
        // Now attempt one more deposit (would overflow to 0)
        vm.deal(address(this), 1);
        (bool success, ) = address(c).call{value: 1}("");
        // The reference accepts this call (success == true), the modified version reverts (success == false)
        assertTrue(success);
    }
}

