        require(ok);
        // Contract balance is 1 wei
        // Owner calls withdrawAll()
        vm.prank(owner);
        c.withdrawAll();
        // Assert that contract balance is 0 (reference: withdrawAll sends all, bug: sends 0)
        assertEq(address(c).balance, 0);
    }
}

